add(106,'''import {assert,spawnNode} from '../../shared/lab.mjs';const r=await spawnNode(['--test','config.test.mjs']);console.log(r.stdout);assert.equal(r.code,0,r.stderr);''','Boundary tests check valid ports and reject malformed/unsafe input.',files={'config.mjs':"export function port(value){if(!/^\\d+$/.test(String(value)))throw Error('Invalid port');const n=Number(value);if(!Number.isInteger(n)||n<1||n>65535)throw Error('Invalid port');return n;}",'config.test.mjs':"import test from 'node:test';import assert from 'node:assert/strict';import {port} from './config.mjs';test('port boundaries',()=>{assert.equal(port('3000'),3000);assert.equal(port(1),1);assert.equal(port(65535),65535);for(const input of [0,-1,65536,'abc',''])assert.throws(()=>port(input),/Invalid port/);});"})
add(107,'''import {assert,spawnNode} from '../../shared/lab.mjs';const r=await spawnNode(['--test','async.test.mjs']);console.log(r.stdout);assert.equal(r.code,0,r.stderr);''','A real HTTP fixture uses an OS-assigned port; test cleanup closes it even when assertions fail.',files={'async.test.mjs':"import test from 'node:test';import assert from 'node:assert/strict';import {createServer} from 'node:http';import {listen,close,temp,fs,join} from '../../shared/lab.mjs';test('HTTP fixture owns resources',async t=>{await using lab=await temp();await fs.writeFile(join(lab.path,'record'),'fixture');const server=createServer((q,s)=>s.end('ok'));const base=await listen(server);t.after(()=>close(server));assert.equal(await(await fetch(base)).text(),'ok');});"})
add(108,'''import {pgLab} from '../../shared/postgres.mjs';import {buildTaskApi,registerAndLogin} from '../../shared/task-api.mjs';import {randomBytes} from 'node:crypto';import assert from 'node:assert/strict';await using db=await pgLab();const app=await buildTaskApi({pool:db.pool,key:randomBytes(32)});try{const user=await registerAndLogin(app);const response=await app.inject({method:'POST',url:'/tasks',headers:user.headers,payload:{title:'integration fixture'}});assert.equal(response.statusCode,201);const created=response.json();const row=(await db.pool.query('SELECT title FROM tasks WHERE id=$1',[created.id])).rows[0];assert.equal(row.title,'integration fixture');console.log('HTTP contract and real PostgreSQL persistence verified');}finally{await app.close();}''','A real Fastify request persists a row that is verified through a separate SQL query; an isolated schema is removed afterward.',mode='postgres',deps=['pg','fastify','jose'])
add(109,'''import {assert,spawnNode} from '../../shared/lab.mjs';const r=await spawnNode(['--test','timers.test.mjs']);console.log(r.stdout);assert.equal(r.code,0,r.stderr);''','Mock time advances exactly to a deadline without real sleeping; timer mocks restore after the test.',files={'timers.test.mjs':"import test from 'node:test';import assert from 'node:assert/strict';test('deadline boundaries',t=>{t.mock.timers.enable({apis:['setTimeout']});const call=t.mock.fn();setTimeout(call,100);t.mock.timers.tick(99);assert.equal(call.mock.callCount(),0);t.mock.timers.tick(1);assert.equal(call.mock.callCount(),1);});"})
add(110,'''import fc from 'fast-check';import assert from 'node:assert/strict';import {encode,decode} from './binary.mjs';fc.assert(fc.property(fc.uint8Array({maxLength:1024}),bytes=>{assert.deepEqual(decode(encode(bytes)),bytes);}),{numRuns:1000,seed:42});assert.throws(()=>decode(Uint8Array.of(0,0,0)));console.log('1000 seeded round trips plus truncated-header boundary passed');''','Generated byte arrays round-trip through the actual codec; the seed makes failures reproducible.',files={'binary.mjs':"export function encode(bytes){const out=Buffer.alloc(4+bytes.length);out.writeUInt32BE(bytes.length);out.set(bytes,4);return out;}export function decode(bytes){const b=Buffer.from(bytes);if(b.length<4)throw Error('Truncated');const n=b.readUInt32BE();if(n>1024||b.length!==n+4)throw Error('Invalid length');return Uint8Array.from(b.subarray(4));}"},deps=['fast-check'])
add(111,'''import {assert,spawnNode} from '../../shared/lab.mjs';for(const file of ['baseline.test.mjs','complete.test.mjs']){const r=await spawnNode(['--test','--experimental-test-coverage',file]);console.log(file,r.stdout);assert.equal(r.code,0,r.stderr);}''','The real coverage report changes when a negative-total branch is tested. No coverage percentage is fabricated.',files={'discount.mjs':"export function discount(total,member){if(total<0)throw Error('Invalid total');return member?total*0.9:total;}",'baseline.test.mjs':"import test from 'node:test';import assert from 'node:assert/strict';import {discount} from './discount.mjs';test('member total',()=>assert.equal(discount(100,true),90));",'complete.test.mjs':"import test from 'node:test';import assert from 'node:assert/strict';import {discount} from './discount.mjs';test('all behaviors',()=>{assert.equal(discount(100,true),90);assert.equal(discount(100,false),100);assert.throws(()=>discount(-1,true),/Invalid total/);});"})
add(112,'''import {ESLint} from 'eslint';import prettier from 'prettier';import assert from 'node:assert/strict';const lint=new ESLint({overrideConfigFile:new URL('./eslint.config.mjs',import.meta.url).pathname.replace(/^\\/(C:)/,'$1')});const [bad]=await lint.lintText('const unused = 1; missingName();',{filePath:'fixture.mjs'});console.log(bad.messages.map(x=>({rule:x.ruleId,message:x.message})));assert.ok(bad.errorCount>=2);const original='const x={a:1};console.log(x)',formatted=await prettier.format(original,{parser:'babel'});assert.equal(await prettier.check(original,{parser:'babel'}),false);assert.equal(await prettier.check(formatted,{parser:'babel'}),true);console.log(formatted);''','ESLint finds actual unused/undefined identifiers; Prettier distinguishes unformatted and formatted source.',files={'eslint.config.mjs':"import js from '@eslint/js';export default [js.configs.recommended,{languageOptions:{globals:{console:'readonly',process:'readonly'}}}];"},deps=['eslint','@eslint/js','prettier'])
add(113,'''import {assert,spawnNode} from '../../shared/lab.mjs';for(const version of ['broken','fixed']){const r=await spawnNode(['--test','discount.test.mjs'],{env:{...process.env,DISCOUNT_VERSION:version}});console.log(version,r.stdout);assert.equal(r.code,version==='fixed'?0:1);}''','The regression test fails on -1900 from the buggy formula and passes on 80 after the fix.','For a breakpoint demonstration run node --inspect-brk broken.mjs, attach DevTools locally, and inspect price=100 and percent=20.',files={'broken.mjs':"export function total(price,percent){return price*(1-percent);}console.log(total(100,20));",'fixed.mjs':"export function total(price,percent){return price*(1-percent/100);}",'discount.test.mjs':"import test from 'node:test';import assert from 'node:assert/strict';const {total}=await import('./'+(process.env.DISCOUNT_VERSION??'fixed')+'.mjs');test('20 percent discount',()=>assert.equal(total(100,20),80));"})
add(114,'''import {build} from 'esbuild';import {assert,spawnNode} from '../../shared/lab.mjs';await build({entryPoints:['src/crash.mjs'],bundle:true,platform:'node',format:'esm',sourcemap:true,outfile:'dist/app.mjs'});const ordinary=await spawnNode(['dist/app.mjs']),mapped=await spawnNode(['--enable-source-maps','dist/app.mjs']);console.log('UNMAPPED',ordinary.stderr,'MAPPED',mapped.stderr);assert.notEqual(ordinary.code,0);assert.notEqual(mapped.code,0);assert.ok(mapped.stderr.includes('src/crash.mjs')||mapped.stderr.includes('src\\\\crash.mjs'));''','The generated bundle fails in both runs; source maps point the second stack back to the original source.',files={'src/crash.mjs':"function fail(){throw Error('course fixture');}\nfail();"},deps=['esbuild'])
add(115,'''import pino from 'pino';import {Writable} from 'node:stream';import assert from 'node:assert/strict';let output='';const sink=new Writable({write(c,e,done){output+=c;done();}});const log=pino({redact:{paths:['password','req.headers.authorization'],remove:true}},sink).child({requestId:'req-001'});log.info({password:'public-demo-password',req:{headers:{authorization:'Bearer public-demo-token'}},action:'login'},'request');log.error({err:Error('fixture failure')},'failed');console.log(output);assert.ok(!output.includes('public-demo-password'));assert.ok(!output.includes('public-demo-token'));assert.equal(JSON.parse(output.split('\\n')[0]).requestId,'req-001');''','Real JSON logs preserve the correlation ID and structured error while removing configured sensitive fields.',deps=['pino'])
add(116,'''import {AsyncLocalStorage} from 'node:async_hooks';import {assert,delay} from '../../shared/lab.mjs';const context=new AsyncLocalStorage(),seen=[];async function request(id,ms){return context.run({id},async()=>{await Promise.resolve();await delay(ms);seen.push(context.getStore().id);});}await Promise.all([request('A',20),request('B',5)]);console.log(seen,context.getStore());assert.deepEqual(seen,['B','A']);assert.equal(context.getStore(),undefined);''','Overlapping requests retain their own IDs and the outer context remains undefined.')
add(117,'''import {channel} from 'node:diagnostics_channel';import assert from 'node:assert/strict';const start=channel('course.operation.start'),done=channel('course.operation.done'),events=[];const listener=value=>events.push(value);start.subscribe(listener);done.subscribe(listener);function operation(value){if(start.hasSubscribers)start.publish({phase:'start',value});try{return value*2;}finally{if(done.hasSubscribers)done.publish({phase:'done'});}}console.log(operation(3));start.unsubscribe(listener);done.unsubscribe(listener);console.log(operation(4),events);assert.equal(events.length,2);''','Diagnostics are emitted synchronously only while subscribed; business results remain 6 and 8.')
add(118,'''import {performance,monitorEventLoopDelay} from 'node:perf_hooks';import {delay,assert} from '../../shared/lab.mjs';const histogram=monitorEventLoopDelay({resolution:5});histogram.enable();try{await delay(20);const before=performance.eventLoopUtilization(),start=performance.now();while(performance.now()-start<40){}await delay(20);const metrics={durationMs:performance.now()-start,utilization:performance.eventLoopUtilization(before).utilization,maxDelayMs:histogram.max/1e6};console.log(metrics);assert.ok(metrics.utilization>=0&&metrics.utilization<=1);assert.ok(metrics.maxDelayMs>0);}finally{histogram.disable();}''','Actual duration, utilization and delay reveal blocking work. Delay nanoseconds are converted to milliseconds.')
add(119,'''import Fastify from 'fastify';import {Registry,Counter,Histogram,Gauge} from 'prom-client';import assert from 'node:assert/strict';const register=new Registry(),requests=new Counter({name:'app_requests_total',help:'Requests',labelNames:['outcome'],registers:[register]}),duration=new Histogram({name:'app_duration_seconds',help:'Duration',registers:[register]}),active=new Gauge({name:'app_inflight',help:'Active',registers:[register]}),app=Fastify();app.get('/work',async q=>{active.inc();const stop=duration.startTimer();try{if(q.query.fail)throw Error('fixture failure');requests.inc({outcome:'ok'});return{ok:true};}catch(e){requests.inc({outcome:'error'});throw e;}finally{stop();active.dec();}});app.get('/metrics',async(q,r)=>r.type(register.contentType).send(await register.metrics()));try{await app.inject('/work');await app.inject('/work?fail=1');const metrics=(await app.inject('/metrics')).body;console.log(metrics);assert.ok(metrics.includes('outcome="ok"'));assert.ok(metrics.includes('outcome="error"'));assert.equal((await active.get()).values[0].value,0);}finally{await app.close();}''','Actual Prometheus text includes bounded success/error labels, histogram samples and an in-flight gauge that returns to zero.',deps=['fastify','prom-client'])
write('shared/telemetry.mjs', '''
import {NodeSDK} from '@opentelemetry/sdk-node';import {InMemorySpanExporter,SimpleSpanProcessor} from '@opentelemetry/sdk-trace';
export async function telemetry(){const exporter=new InMemorySpanExporter();const sdk=new NodeSDK({spanProcessors:[new SimpleSpanProcessor(exporter)]});await sdk.start();return{sdk,exporter};}
''')
add(120,'''import {fork} from 'node:child_process';import {trace,context,propagation} from '@opentelemetry/api';import {telemetry} from '../../shared/telemetry.mjs';import assert from 'node:assert/strict';const {sdk,exporter}=await telemetry(),child=fork(new URL('./service-b.mjs',import.meta.url),{stdio:['ignore','inherit','inherit','ipc']});const port=await new Promise((resolve,reject)=>{child.once('message',m=>resolve(m.port));child.once('error',reject);});try{await trace.getTracer('service-a').startActiveSpan('GET downstream',async span=>{try{const headers={};propagation.inject(context.active(),headers);const response=await fetch('http://127.0.0.1:'+port,{headers});const body=await response.json();assert.equal(body.traceId,span.spanContext().traceId);assert.equal(body.parentSpanId,span.spanContext().spanId);console.log('Same trace ID across two processes; child has a distinct span ID:',body.spanId!==span.spanContext().spanId);}finally{span.end();}});assert.equal(exporter.getFinishedSpans().length,1);}finally{child.send('stop');await new Promise(r=>child.once('exit',r));await sdk.shutdown();}''','Two actual Node processes propagate W3C trace context through HTTP. Trace IDs and parent-child relationships are asserted.',files={'service-b.mjs':"import {createServer} from 'node:http';import {trace,context,propagation} from '@opentelemetry/api';import {telemetry} from '../../shared/telemetry.mjs';const {sdk}=await telemetry();const server=createServer((q,r)=>{const parent=propagation.extract(context.active(),q.headers),span=trace.getTracer('service-b').startSpan('receive',undefined,parent);const result={traceId:span.spanContext().traceId,spanId:span.spanContext().spanId,parentSpanId:trace.getSpanContext(parent)?.spanId};r.setHeader('content-type','application/json');r.end(JSON.stringify(result));span.end();});server.listen(0,'127.0.0.1',()=>process.send({port:server.address().port}));process.on('message',async m=>{if(m==='stop'){await new Promise(r=>server.close(r));await sdk.shutdown();process.disconnect();}});"},deps=['@opentelemetry/api','@opentelemetry/sdk-node','@opentelemetry/sdk-trace'])
